 "content": "def transform(grid):
    h = len(grid)
    if h % 4:
        raise ValueError("expected four stacked layers")
    layer_h = h // 4
    out = []
    for r in range(layer_h):
        row = []
        for c in range(len(grid[0])):
            value = 0
            for layer in range(4):
                candidate = grid[layer * layer_h + r][c]
                if candidate:
                    value = candidate
                    break
            row.append(value)
        out.append(row)
    return out
